package org.sigilaris.conformance

import scodec.bits.ByteVector

/** Executed JVM codec output; shared JVM/Scala.js consumers assert every byte.
  * Regenerate only after reviewing a protocol-compatible source change.
  */
@SuppressWarnings(Array("org.wartremover.warts.Equals"))
object V2GoldenVectors:
  val expected: Map[String, String] = Map(
    "input-manifest" -> "",
    "input-descriptor" -> "",
    "footprint" -> "000000000000000201010303010101020104",
    "classification-statement" -> "",
    "plan-entry" -> "",
    "nonempty-plan" -> "",
    "empty-plan"          -> "00000000000000020000",
    "reservation-witness" -> "000000000000000104010102010202010301010402",
    "witness-chunk" -> "0000000000000001609b421ef9b4f2db08ffc2f056a47b3b0a61e2db11358cdde6c3630a552f15250000000000000000000000000000000115000000000000000104010102010202010301010402",
    "protocol-manifest" -> "",
    "lock-subject" -> "",
    "lock-signing-preimage" -> "",
    "lock-certificate" -> "",
    "effect-subject" -> "",
    "effect-signing-preimage" -> "",
    "effect-certificate" -> "",
  )

  def validate(actual: Vector[(String, ByteVector)]): Unit =
    assert(actual.size == expected.size, "golden vector membership changed")
    assert(
      actual.map(_._1).distinct.size == actual.size,
      "duplicate vector name",
    )
    actual.foreach: (name, bytes) =>
      assert(
        expected.get(name).contains(bytes.toHex),
        s"canonical vector mismatch: $name",
      )
